import { Schema, model, type InferSchemaType, type HydratedDocument } from 'mongoose';
import { ROADMAP_ITEM_STATUSES, type RoadmapItemStatus } from '../config/constants.js';

export interface RoadmapItem {
  /** MongoDB document id, generated by the sub-document schema. */
  _id?: unknown;
  order: number;
  title: string;
  description: string;
  skill?: Schema.Types.ObjectId;
  skillCode?: string;
  kind: 'learn' | 'practice' | 'project' | 'milestone' | 'assess';
  stage: 'beginner' | 'intermediate' | 'advanced';
  estimatedHours: number;
  completionCriteria: string;
  resourceLinks: Array<{ title: string; url: string }>;
  status: RoadmapItemStatus;
  startedAt?: Date;
  completedAt?: Date;
}

export interface RoadmapMilestone {
  stage: 'beginner' | 'intermediate' | 'advanced';
  title: string;
  completionCriteria: string;
  itemIds: string[];
  completed: boolean;
  completedAt?: Date;
}

export interface RoadmapDocumentFields {
  candidate: Schema.Types.ObjectId;
  career: Schema.Types.ObjectId;
  report: Schema.Types.ObjectId;
  scoringVersion: string;
  title: string;
  summary: string;
  currentDemonstratedSkills: Array<{ skillCode: string; skillName: string; score: number }>;
  priorityGaps: Array<{ skillCode: string; skillName: string; gap: number; priority: string }>;
  items: RoadmapItem[];
  milestones: RoadmapMilestone[];
  progressPercent: number;
  sourceReportTitle: string;
  lastActivityAt: Date;
  createdBy: Schema.Types.ObjectId;
  isSample: boolean;
}

const resourceLinkSchema = new Schema(
  {
    title: { type: String, maxlength: 200 },
    url: { type: String, maxlength: 500 },
  },
  { _id: false },
);

const itemSchema = new Schema<RoadmapItem>(
  {
    order: { type: Number, default: 0 },
    title: { type: String, required: true, maxlength: 200 },
    description: { type: String, default: '', maxlength: 2000 },
    skill: { type: Schema.Types.ObjectId, ref: 'Skill' },
    skillCode: String,
    kind: { type: String, enum: ['learn', 'practice', 'project', 'milestone', 'assess'], default: 'learn' },
    stage: { type: String, enum: ['beginner', 'intermediate', 'advanced'], default: 'beginner' },
    estimatedHours: { type: Number, min: 0, max: 1000, default: 4 },
    completionCriteria: { type: String, default: '', maxlength: 600 },
    resourceLinks: { type: [resourceLinkSchema], default: [] },
    status: { type: String, enum: ROADMAP_ITEM_STATUSES, default: 'not_started' },
    startedAt: { type: Date },
    completedAt: { type: Date },
  },
  { _id: true },
);

const milestoneSchema = new Schema<RoadmapMilestone>(
  {
    stage: { type: String, enum: ['beginner', 'intermediate', 'advanced'], required: true },
    title: { type: String, required: true, maxlength: 200 },
    completionCriteria: { type: String, default: '', maxlength: 600 },
    itemIds: { type: [String], default: [] },
    completed: { type: Boolean, default: false },
    completedAt: { type: Date },
  },
  { _id: false },
);

const roadmapSchema = new Schema<RoadmapDocumentFields>(
  {
    candidate: { type: Schema.Types.ObjectId, ref: 'User', required: true, index: true },
    career: { type: Schema.Types.ObjectId, ref: 'Career', required: true, index: true },
    report: { type: Schema.Types.ObjectId, ref: 'CareerReport', required: true },
    scoringVersion: { type: String, required: true },
    title: { type: String, required: true, maxlength: 200 },
    summary: { type: String, default: '', maxlength: 2000 },
    currentDemonstratedSkills: {
      type: [
        new Schema(
          { skillCode: String, skillName: String, score: Number },
          { _id: false },
        ),
      ],
      default: [],
    },
    priorityGaps: {
      type: [
        new Schema(
          { skillCode: String, skillName: String, gap: Number, priority: String },
          { _id: false },
        ),
      ],
      default: [],
    },
    items: { type: [itemSchema], default: [] },
    milestones: { type: [milestoneSchema], default: [] },
    progressPercent: { type: Number, min: 0, max: 100, default: 0 },
    sourceReportTitle: { type: String, default: '' },
    lastActivityAt: { type: Date, default: () => new Date() },
    createdBy: { type: Schema.Types.ObjectId, ref: 'User', required: true },
    isSample: { type: Boolean, default: false },
  },
  { timestamps: true },
);

roadmapSchema.index({ candidate: 1, career: 1 }, { unique: true });

export type Roadmap = InferSchemaType<RoadmapDocumentFields>;
export type RoadmapDocument = HydratedDocument<RoadmapDocumentFields>;
export const RoadmapModel = model<RoadmapDocumentFields>('Roadmap', roadmapSchema);
